/**
 * Drizzle schema, generated by `drizzle-kit pull` against the live database so
 * it reflects what is actually deployed -- column types, numeric precision,
 * enum values and nullability -- rather than a hand translation of
 * prisma/schema.prisma.
 *
 * Two deliberate edits after generation:
 *   - timestamp and date columns use mode: 'date'. Introspection defaults them
 *     to 'string', but Prisma returned Date objects and the services call
 *     .toISOString() on them, so strings would fail at runtime, not at build.
 *   - the _prisma_migrations bookkeeping table is dropped; it is not domain data.
 *   - every `id` primary key carries $defaultFn(randomUUID). Prisma's
 *     @default(uuid()) was applied by the Prisma client, NOT by the database --
 *     all 41 id columns have no column_default in Postgres -- so without this
 *     every insert fails on a null primary key.
 *   - updated_at columns carry $defaultFn + $onUpdate. Prisma's @updatedAt set
 *     these on both insert and update; Drizzle does nothing unless the column
 *     says so, and they are NOT NULL with no database default, so inserts would
 *     fail and updates would silently leave a stale timestamp.
 *
 * Regenerate with: npm run db:pull
 */
import { pgTable, varchar, timestamp, text, integer, jsonb, uniqueIndex, foreignKey, boolean, index, numeric, date, pgEnum } from "drizzle-orm/pg-core"
import { sql } from "drizzle-orm"
import { randomUUID } from "node:crypto"

