export const users = pgTable("users", {
	id: text().primaryKey().notNull().$defaultFn(() => randomUUID()),
	agencyId: text("agency_id"),
	firstName: text("first_name").notNull(),
	lastName: text("last_name").notNull(),
	email: text().notNull(),
	phone: text(),
	passwordHash: text("password_hash").notNull(),
	isEmailVerified: boolean("is_email_verified").default(false).notNull(),
	emailVerifyToken: text("email_verify_token"),
	emailVerifyExpires: timestamp("email_verify_expires", { precision: 3, mode: 'date' }),
	passwordResetToken: text("password_reset_token"),
	passwordResetExpires: timestamp("password_reset_expires", { precision: 3, mode: 'date' }),
	refreshTokenHash: text("refresh_token_hash"),
	status: entityStatus().default('active').notNull(),
	lastLoginAt: timestamp("last_login_at", { precision: 3, mode: 'date' }),
	deletedAt: timestamp("deleted_at", { precision: 3, mode: 'date' }),
	createdAt: timestamp("created_at", { precision: 3, mode: 'date' }).default(sql`CURRENT_TIMESTAMP`).notNull(),
	updatedAt: timestamp("updated_at", { precision: 3, mode: 'date' }).notNull().$defaultFn(() => new Date()).$onUpdate(() => new Date()),
}, (table) => [
	uniqueIndex("users_email_key").using("btree", table.email.asc().nullsLast().op("text_ops")),
	foreignKey({
			columns: [table.agencyId],
			foreignColumns: [agencies.id],
			name: "users_agency_id_fkey"
		}).onUpdate("cascade").onDelete("set null"),
]);

